// Custom sampler stubs (mapped to noise texture)
#define sampler_rand00 sampler_noise_lq
sampler sampler_rand00;
shader_body
{
vec2 ac = vec2(q1,q2);
vec2 mu = vec2(q3,q4);
vec2 c = vec2(q5,q6);
vec2 d = vec2(q7,q8);
vec2 z = (uv-0.5)*uAspect.wz;
// (c*z + d)
vec2 czd = vec2(z.x*c.x-z.y*c.y,z.x*c.y-z.y*c.x)*uAspect.yx + d;
// mu/(cz+d)
vec2 moebius = vec2( mu.x*czd.x + mu.y*czd.y , mu.y*czd.x-mu.x*czd.y )/(czd.x*czd.x+czd.y*czd.y) + ac;
d = (vec2(1.0)/uTexSize) * 4.0;
vec3 dx = ( GetBlur1(uv+vec2( 1.0 , 0.0 )*d)-GetBlur1(uv-vec2( 1.0 , 0.0 )*d).xy );
vec3 dy = ( GetBlur1(uv+vec2( 0.0 , 1.0 )*d)-GetBlur1(uv-vec2( 0.0 , 1.0 )*d).xy );
moebius = 0.5 + (1.0 - abs( fract( moebius * 0.5  - vec2(dx.y,dy.y)*0.2 + vec2(dx.x,dy.x)*0.1) * 2.0 - 1.0 )-0.5)*0.99;
ret = tex2d(sampler_rand00, fract(moebius));
ret = mix(ret,-2,GetPixel(uv + vec2(dx.y,dy.y)*0.1).x*0.1);
ret = mix(ret,-1,GetPixel(uv - vec2(dx.z,dy.z)*0.024).z*0.4);
ret = mix(ret, 1.0 ,clamp01(GetPixel(uv).y-GetBlur3(uv).y * 2.0));
//ret = GetPixel(uv).x;
}

